// CSD_RATIONALE_BEGIN
// Attempt 5: Principled dead-end avoidance to fix '!' repetition loops.
//
// Root-cause analysis from attempt feedback:
//   1. '!!!...' loops: Model wants to write operators not in the grammar (=, ^, **, if).
//      The hard mask blocks them, but '!' or another token is valid-yet-dead-end in the
//      parser state. SafePenalizedConstrainedStep(["!"],4.0) only penalises one token;
//      DeadEndAvoidingStep(maxRetries=5) is the principled fix — it detects ANY dead-end
//      token, masks it, and resamples, regardless of which specific token triggered the loop.
//   2. '* 12 // 12' repetition loops: parser allows arbitrarily long arithmetic chains.
//      Tightening maxSpanLength from 50 → 20 catches these loops sooner and hands off to
//      CloseSpanWithinBudget which can roll back to the last completable prefix.
//   3. attempt 2's SafeRepetitionPenaltyStep on full 'generated' penalised variable names
//      (n1,p1,...) appearing in reasoning, causing wrong expressions. DeadEndAvoidingStep
//      never penalises variable names — it only masks per-step dead-end choices.
//   4. 7-9 unclosed spans: handled by closeReserve=70 + EOS-inside-span CloseSpanWithinBudget
//      + final cleanup.
//   5. Guidance explicitly bans =, ^, **, if, ! inside << >>; emphasises int().
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Force-close branch (remaining<=closeReserve || |currentConstrainedOut|>=maxSpanLength):
//     We are inside a span, so loop invariant gives parser.IsValidPrefix(currentConstrainedOut)
//     and |currentConstrainedOut|<=|generated|. CloseSpanWithinBudget postcondition:
//     insideOut ==> parser.IsValidPrefix(currentOut). Both closed and still-open paths
//     satisfy the invariant. ✓
//
//   Outside-span branch (!insideConstrainedOut):
//     insideConstrainedOut was false; implication is vacuous. We flip it to true only when
//     RenderedEndsWith(generated,"<<"), setting currentConstrainedOut:=[] which satisfies
//     parser.IsValidPrefix([]) by the method precondition. ✓
//
//   IsCompletePrefix branch:
//     CloseConstrainedSpan sets insideConstrainedOut:=false; implication vacuously true. ✓
//
//   DeadEndAvoidingStep branch, non-EOS path:
//     DeadEndAvoidingStep applies grammar hard-mask; returned token is parser-valid.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   DeadEndAvoidingStep branch, EOS path:
//     generated/currentConstrainedOut unchanged before CloseSpanWithinBudget.
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   Final cleanup: CloseSpanWithinBudget postcondition as above. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Force-close branch: CloseSpanWithinBudget(remaining) gives |cg|<=|generated|+remaining.
//     By loop invariant: |cg|<=|generatedPrefix|+steps+(maxSteps-steps)=|generatedPrefix|+maxSteps.
//     After steps:=maxSteps: |generated|<=|generatedPrefix|+steps. ✓
//
//   Outside-span: steps+=1; generated grows by at most 1 token. ✓
//
//   IsCompletePrefix: steps+=1; CloseConstrainedSpan appends ">>" (1 token).
//     |generated|+1 <= |generatedPrefix|+steps_old+1 = |generatedPrefix|+steps_new. ✓
//
//   DeadEndAvoidingStep, non-EOS: steps+=1; AppendConstrainedToken adds 1 token.
//     |generated|+1 <= |generatedPrefix|+steps_old+1 = |generatedPrefix|+steps_new. ✓
//
//   DeadEndAvoidingStep, EOS: steps incremented; generated unchanged at that point.
//     |generated|<=|generatedPrefix|+(steps-1). remainAfterStep=maxSteps-steps.
//     |cg|<=|generated|+remainAfterStep<=|generatedPrefix|+(steps-1)+(maxSteps-steps)
//           =|generatedPrefix|+maxSteps-1 < |generatedPrefix|+maxSteps.
//     After steps:=maxSteps: bound holds. ✓
//
//   Final cleanup: same argument as force-close branch. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap EVERY symbolic expression in << >> delimiters. " +
  "End with exactly: The final answer is <<expression>>. " +
  "Inside << >> use ONLY: variable names from the problem, numbers, +, -, *, /, //, %, (), int(). " +
  "NEVER use =, ^, **, if, else, :, ! or any assignment inside << >>. " +
  "Use int() to produce whole-number results. Use // for floor division. " +
  "Write one finished expression per << >> span. Do not show variable assignments inside << >>.");

var closeReserve: nat := 70;
var maxSpanLength: nat := 20;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && (remaining <= closeReserve || |currentConstrainedOut| >= maxSpanLength) {
    // Budget running low OR span is suspiciously long (loop): force-close with full remaining budget
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    // Outside a span: free generation
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Span is complete: close immediately
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Normal constrained step with dead-end avoidance
    // DeadEndAvoidingStep detects tokens valid now but leading to no valid continuation
    // (e.g. '!' after '!!!!', '^' attempts, '=' attempts) and resamples up to 5 times
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next, success := helpers.DeadEndAvoidingStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, 5
    );
    steps := steps + 1;
    if next == eosToken {
      // EOS inside span: attempt salvage with remaining budget
      var remainAfterStep: nat := maxSteps - steps;
      if remainAfterStep > 0 {
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainAfterStep
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := maxSteps;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any remaining open span
if insideConstrainedOut && steps < maxSteps {
  var remaining2: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining2
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

